import itertools
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set(U):
    # U is a tuple of 3 distinct integers
    u1, u2, u3 = U

    # Condition 1: gcd of all three is 1
    if gcd_three(u1, u2, u3) != 1:
        return False

    # Condition 2: For any pair, the third element divides their product
    # Pair (u1, u2) -> u3 must divide u1*u2
    if (u1 * u2) % u3 != 0:
        return False
    # Pair (u1, u3) -> u2 must divide u1*u3
    if (u1 * u3) % u2 != 0:
        return False
    # Pair (u2, u3) -> u1 must divide u2*u3
    if (u2 * u3) % u1 != 0:
        return False

    return True

good_sets_found = []
product_m_values = set()

# Search for sets U where elements are in {1, 2, ..., 10}
for U in itertools.combinations(range(1, 11), 3):
    if is_good_set(U):
        good_sets_found.append(U)
        m = U[0] * U[1] * U[2]
        product_m_values.add(m)

# Sort the products
sorted_products = sorted(list(product_m_values))

print(f"Total good sets found: {len(good_sets_found)}")
print(f"List of unique products m (sorted): {sorted_products}")

import itertools
import math

def gcd_triplet(a, b, c):
    return math.gcd(a, math.gcd(b, c))

def check_good_set(U):
    # Constraint 1: |U| >= 3 (Given |U|=4)

    # Constraint 2: GCD of any three distinct elements is 1
    triplets = list(itertools.combinations(U, 3))
    for a, b, c in triplets:
        if gcd_triplet(a, b, c) != 1:
            return False

    # Constraint 3: For any two distinct elements a, b in U, 
    # there exists another element c in U \ {a, b} such that c divides ab.
    pairs = list(itertools.combinations(U, 2))
    for a, b in pairs:
        ab = a * b
        found_divisor = False
        for c in U:
            if c != a and c != b:
                if ab % c == 0:
                    found_divisor = True
                    break
        if not found_divisor:
            return False

    return True

# The search space is numbers <= 8.
S = list(range(1, 9))
good_sets = []
products = {}

# Iterate over all subsets of size 4
for U_tuple in itertools.combinations(S, 4):
    U = list(U_tuple)
    if check_good_set(U):
        # Found a good set
        good_sets.append(U)
        m = 1
        for x in U:
            m *= x
        products[tuple(sorted(U))] = m

print("Found Good Sets (as sorted tuples):")
for U in sorted(good_sets):
    print(U)

print("\nProducts m for each good set:")
for U_tuple, m in products.items():
    print(f"Set {U_tuple} -> Product {m}")

