import math
from itertools import combinations

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def check_good_set(U):
    u1, u2, u3 = sorted(U)

    # Condition 1: GCD of three is 1
    if gcd(u1, gcd(u2, u3)) != 1:
        return False

    # Condition 2: Divisibility property
    # u3 | u1*u2
    if (u1 * u2) % u3 != 0:
        return False
    # u2 | u1*u3
    if (u1 * u3) % u2 != 0:
        return False
    # u1 | u2*u3
    if (u2 * u3) % u1 != 0:
        return False

    return True

def is_w8_family_product(m):
    """Checks if m is the product (p1*p2*p3)^2 where p1, p2, p3 are distinct primes."""
    if m <= 0:
        return False

    # Check if m is a perfect square
    k = int(math.sqrt(m))
    if k * k != m:
        return False

    # Check if k is a product of three distinct primes
    if k < 2:
        return False

    prime_factors = {}
    n = k
    d = 2
    while d * d <= n:
        while n % d == 0:
            prime_factors[d] = prime_factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        prime_factors[n] = prime_factors.get(n, 0) + 1

    # Must have exactly 3 distinct prime factors, each with exponent 1
    if len(prime_factors) != 3:
        return False

    for count in prime_factors.values():
        if count != 1:
            return False

    return True

# Search space: max(U) < 50
UPPER_BOUND = 50
good_numbers_non_w8 = []

# Iterate over all combinations of three distinct integers less than 50
for U_tuple in combinations(range(1, UPPER_BOUND), 3):
    U = list(U_tuple)

    if check_good_set(U):
        m = U[0] * U[1] * U[2]

        if not is_w8_family_product(m):
            good_numbers_non_w8.append(m)

# Sort and analyze
good_numbers_non_w8.sort()

print(f"Total good numbers found (non-W8) with max(U) < {UPPER_BOUND}: {len(good_numbers_non_w8)}")
if len(good_numbers_non_w8) >= 20:
    print(f"The 20th smallest good number (non-W8) is: {good_numbers_non_w8[19]}")
else:
    print("Not enough non-W8 good numbers found.")

